INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Приход маунфилд 03.10.26', 'Три счёта Маунфелд от 01.10.2026 (№ 39324, 39341, 39344) — 498 строк. Одинаковые товары с одинаковой ценой объединены, количество сложено: 314 строк. Цена = «Всего с НДС» / количество × 1,2, округлено вверх до рубля; сумма = цена × количество. Итого: 1 387 шт, 236 089 руб. (в счетах 196 170,14 с НДС).', '/converted/prihod-maunfild-03-10-26.xlsx', 'Приход маунфилд 03.10.26.xlsx', 'converted/prihod-maunfild-03-10-26.xlsx', 16363);